    public static class LongStory
    {
        static readonly string[][] Arcs={
            new[]{"Список переселенцев","Дома у трассы","Заявление соседа","Последний подрядчик","Открытая улица","Адрес моего будущего"},new[]{"Исчезнувшая смена","Транзитный номер","Патрульный заговор","Операция на набережной","Дело командира","Цена последнего значка"},new[]{"Федеральный узел","Архив «Север»","Зеркальный информатор","Счёт подрядчика","Последняя ячейка","Горизонт без тени"},new[]{"Приказ дальнего штаба","Перехваченный конвой","Склад резерва","Рубеж на аэродроме","Гарнизон под угрозой","Пятидесятая вахта"},new[]{"Смена в северном округе","Бригада на трассе","Запас для реанимации","Перевозка без права опоздать","Одна бригада на штат","Жизнь после смены"},new[]{"Огонь в промзоне","Уязвимый ангар","Перекрытый выход","Проверка поставщика","Последняя большая тревога","Вернуться всей командой"},new[]{"Рейс в неизвестность","Семейный архив","Открытка с аэродрома","Тариф доверия","Возвращение пассажира","Своя дорога домой"},new[]{"Склад за границей округа","Партия под замену","Контракт без подписи","Вес чужой ответственности","Последний получатель","Дорога без обмана"},new[]{"Двигатель после аварии","Поддельный номер","Сервисный договор","Заказ из дальнего округа","Мастерская под своим именем","Гарантия на будущее"},new[]{"Чужой двор","Сделка у ангара","Районный посредник","Зелёный маршрут","Свои против чужих","Кому принадлежит улица"},new[]{"Программа новых округов","Подряд без конкурса","Голоса жителей","Кабинетная проверка","Заседание всего штата","Обещание перед городом"},new[]{"Новая учебная группа","Маршрут тяжёлого транспорта","Экзамен инструктора","Лицензия округа","Единый реестр школ","Правила для всех дорог"},new[]{"Ночная караульная","Ключ из второго блока","Служебный пропуск","Ложная тревога","Проверка начальника смены","Смена без потерь"},new[]{"Архив личного дела","Тюремный свидетель","Работа ради подписи","Письмо за периметр","Проверка перед комиссией","Дорога за стену"},new[]{"Заказ без гарантий","Имя в старом досье","Схрон на окружной","Свободный посредник","Сделка против заказчика","Своё имя навсегда"}
        };
        static readonly string[] StageTitles={"Первый сигнал","Проверка следа","Выбор стороны","Решающая встреча","Итог операции"};
        static readonly string[] StageBriefs={"Контакт передал новый адрес и просит лично проверить исходные данные. Выполни выездное поручение и привези подтверждение.","Первая зацепка ведёт в соседний округ. Проверь вторую точку, выполни профильную задачу и сохрани результат.","Есть два маршрута: открытое сотрудничество или проверка через личный контакт. Выбери способ продолжения и заверши встречу.","Осталось пройти самый трудный этап. Подготовь транспорт и оснащение, выполни задачу на месте и вернись с результатом.","Сведи материалы этой операции и передай их своему контакту. Решения прошлых глав определяют, с кем ты продолжишь работу."};
        public static string Text(int role,int index)
        {int arc=index/5,stage=index%5;return Arcs[role][arc]+" · "+StageTitles[stage]+"|"+StoryBook.Stories[role].Contact+": «"+Arcs[role][arc]+"». "+StageBriefs[stage]+(index==29?" Это пятидесятая глава и окончательное завершение истории.":"");}
