    public sealed partial class GameRoot
    {
        Mission MakeLongStoryMission(int role,int chapter,int choice)
        {
            int index=chapter-20,stage=index%5,arc=index/5;
            if(role==13){var mission=PrisonMission(chapter==StoryBook.ChapterCount-1 && choice==1?0:1);mission.Release=chapter==StoryBook.ChapterCount-1 && choice==0;return mission;}
            if(role==12)return new Mission("Проверка караула","Проверь поручение секции, периметр и журнал смены.",1200+index*90,false,new[]{new Vector3(1005+stage*5,1,-470),new Vector3(1130,1,-410-arc*8),WorldBuilder.Places[12].Position},"Проверь назначенную секцию","Заверши обход и сверку пропусков","Передай рапорт начальнику смены");
            Vector3 home=WorldBuilder.Places[role].Position;
            Vector3 district=StateBuilder.ExpansionCenters[(role+arc+choice)%4]+new Vector3(6,0,30+stage*22);
            Vector3 city=(index+choice)%3==0?StateBuilder.SanFierro:(index+choice)%3==1?StateBuilder.LasVenturas:Vector3.zero;city+=new Vector3(6,0,40+stage*20);
            bool armed=role==1||role==2||role==3||role==9||role==14;
            var job=new Mission("Продолжение истории","Операция нового округа",1800+index*110,true,new[]{role==8?home:district,role==8?district:city,home},role==4?"Окажи помощь и подготовь пациента":role==5?"Потуши опасный очаг":role==8?"Забери оборудование мастерской":role==6?"Встреть пассажира":role==7?"Проверь партию груза":"Проверь адрес и выполни поручение",role==8?"Выполни ремонт на месте":"Выполни встречу и получи подтверждение","Вернись к своему контакту");
            job.Combat=armed && (stage==3 || index==29);job.Fleeing=(role==9||role==14||role==1||role==2) && stage==1;
            if(stage==3 && !armed)job.TimeLimit=1200;return job;
        }
    }
}
